    # its outermost marks with the gap color 2.
    for r in range(h):
        cols = [c for c in range(w) if grid[r][c] == mark]
        if len(cols) >= 3:
            for c in range(min(cols), max(cols) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        if len(rows) >= 3:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
