            for c in range(w):
                if grid[r][c] != color or comp[r][c] != -1:
                    continue
                comp[r][c] = ncomp
                q = deque([(r, c)])
                while q:
                    y, x = q.popleft()
                    for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
