        # to distinct 4-connected objects. A single connected outline stays open.
        for r in range(h):
            cols = [c for c in range(w) if grid[r][c] == color]
            for a, b in zip(cols, cols[1:]):
                if comp[r][a] != comp[r][b]:
                    for c in range(a + 1, b):
                        if grid[r][c] == bg:
                            out[r][c] = 2
        for c in range(w):
            rows = [r for r in range(h) if grid[r][c] == color]
            for a, b in zip(rows, rows[1:]):
                if comp[a][c] != comp[b][c]:
                    for r in range(a + 1, b):
                        if grid[r][c] == bg:
                            out[r][c] = 2
    return out


