        rows = [r for r in range(h) if grid[r][c] != bg]
        if len(rows) >= 2:
            for r in range(min(rows), max(rows) + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    # Complete the outer frame only on its extreme rows and columns.
    fill_row(r0)
    if r1 != r0:
